#!/bin/sh
# Runs every test headless, JOBS at a time (S336, operator "the heat fixed": 4 on a GREEN PC; JOBS=2 beside agents, JOBS=1
# serial). Results print in list order; a test fails on its exit code, a script error or a parse error. Usage: sh tools/run_tests.sh
GODOT="${GODOT_EXE:-$LOCALAPPDATA/Programs/Godot/Godot_v4.7.2-stable_win64.exe}"
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
JOBS="${JOBS:-4}"
TMP="$(mktemp -d)"
TESTS="plain_words_test ring_ropes_entry_test guard_weave_test glove_cut_test training_preview_test fighter_goal_test membership_test game_money_test amateur_booking_test bout_rules_test move_mastery_test round_script_test round_style_test habit_beats_test combos_test combo_words_test corner_card_test exchanges_test habit_fix_test coach_notes_test fight_feel_test boxer_footwork_test ring_feet_test hit_snap_gain_test body_keep_test hit_flash_test fighter_profile_test knockdowns_test bout_stoppage_test save_load_test test_jump_test tale_of_tape_test corner_jobs_test beat_clips_test balance_harness_test fight_words_contract_test range_breath_test clinch_beats_test burst_shape_test inside_beats_test inside_exits_test body_map_test body_load_test body_rates_test body_track_test pace_aim_test body_figure_test body_turn_test faces_test call_evidence_test short_punch_test gym_bills_test money_close_test injury_roll_test training_load_test training_week_test training_plan_test combo_builder_test combo_flow_test body_report_test injuries_test season_path_test champ_draw_test champs_test pro_debut_test bout_burn_test the_read_test grapple_db_test grapple_pose_test grapple_graph_test grapple_grip_test grapple_timing_test grapple_contact_test strike_map_test ground_rules_test strike_browser_test move_clips_test next_step_test wrestle_chains_test tie_clips_test tieup_panel_test tieup_plan_test grey_reason_test plan_board_test plan_fight_test plan_bout_test opp_file_test plan_templates_test clinch_rest_test fight_flow_test knockdown_ring_test plan_screen_test next_step_card_test attr_board_test tape_clips_test tape_room_test fight_meters_test ring_lens_test belt_road_test corner_stats_test face_marks_test week_plan_test recruit_test perk_fight_test week_actual_test combo_odds_test plan_test_it_test peak_camp_test week_phase_test week_twist_test week_coach_test week_board_clarity_test tips_test move_book_test plan_lines_test game_plan_test week_opp_test review_reveal_test push_back_test trust_fight_test no_gi_test bjj_side_test stripe_call_test drill_pick_test tip_notes_test golden_path_test rival_past_test week_cause_test skill_awards_test plan_record_test male_boxer_test no_pronoun_test test_day_test male_bodies_test weigh_forecast_test plan_record_ui_test women_classes_test tired_legs_test passed_stamp_test plan_file_test combo_plan_test bjj_mat_test bjj_coach_test playtest_s375_test camp_cards_test callout_pop_test theatre_test camp_protocol_test film_edge_test night_line_test week_strip_test spar_nights_test gauges_test hover_ghosts_test test_pad_week test_pad_edit drill_card_test test_pad_review card_flip_test holo_off_test evenings_test move_tip_test plan_cards_test plan_tray_test move_pics_test knee_track_test foot_plant_test owned_mocap_test bjj_tree_test bjj_tree_odds_test bjj_tree_sim_test bjj_tree_ui_test corner_lens_test first_week_test roster_summary_test records_test fight_why_test week_read_test poster_reveal_test sound_bank_test coach_check_test promo_shot_test bout_read_test bjj_match_test bjj_finish_test bjj_open_night_test bjj_clash_test pad_view_test corner_warm_test counter_cut_test home_look_test hud_shown_test attendance_test crowd_room_test fight_polish_test credits_test truth_pass_test menus_round4_test plan_read_test"
for t in $TESTS; do [ -f "$ROOT/tests/$t.gd" ] && echo "$t"; done | xargs -P "$JOBS" -I{} sh -c   '"$0" --headless --audio-driver Dummy --path "$1" --script "res://tests/{}.gd" > "$2/{}.out" 2>&1; echo $? > "$2/{}.rc"'   "$GODOT" "$ROOT" "$TMP"
fail=0
for t in $TESTS; do
  [ -f "$ROOT/tests/$t.gd" ] || continue
  code=$(cat "$TMP/$t.rc" 2>/dev/null || echo 99)
  if grep -qE "SCRIPT ERROR|Parse Error|Failed to load script" "$TMP/$t.out" 2>/dev/null; then code=9; fi
  if [ "$code" -eq 0 ]; then echo "PASS $t"; else echo "FAIL $t (exit $code)"; tail -40 "$TMP/$t.out"; fail=1; fi
done
rm -rf "$TMP"
exit $fail
